const ProductRow = memo(function ProductRow({ product, onSelect }: RowProps) {
  return <li onClick={() => onSelect(product.id)}>{product.name}</li>;
});

function ProductList({ products, filter }: Props) {
  const [selected, setSelected] = useState<number | null>(null);

  // Without these, every render creates a new array and a new function,
  // so memo(ProductRow) would never skip anything.
  const visible = useMemo(() => products.filter((p) => p.name.includes(filter)), [products, filter]);
  const handleSelect = useCallback((id: number) => setSelected(id), []);

  return <ul>{visible.map((p) => <ProductRow key={p.id} product={p} onSelect={handleSelect} />)}</ul>;
}
